import{_ as e,a as d,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse(`{"title":"List EU Withdrawals","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-eu-withdrawals","title":"List Own EU Withdrawals","description":"Retrieve a paginated list of the authenticated customer's own EU right-of-withdrawal declarations, newest first.","request":"GET /api/shop/eu-withdrawals\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"[\\n  {\\n    \\"id\\": 7,\\n    \\"uuid\\": \\"b2f1c0de-5a2e-4d7a-9f2e-3c1a2b4d5e6f\\",\\n    \\"orderId\\": 12,\\n    \\"orderIncrementId\\": \\"000000012\\",\\n    \\"isGuest\\": false,\\n    \\"customerEmail\\": \\"jane@example.com\\",\\n    \\"status\\": \\"received\\",\\n    \\"reasonText\\": \\"Changed my mind.\\",\\n    \\"receivedAt\\": \\"2026-07-20T09:00:00+00:00\\",\\n    \\"confirmationSentAt\\": \\"2026-07-20T09:00:05+00:00\\",\\n    \\"declinedAt\\": null,\\n    \\"declinedReason\\": null,\\n    \\"refundedAt\\": null,\\n    \\"refundNote\\": null,\\n    \\"createdAt\\": \\"2026-07-20T09:00:00+00:00\\",\\n    \\"updatedAt\\": \\"2026-07-20T09:00:05+00:00\\"\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"403 Forbidden","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"}]}]},"headers":[],"relativePath":"api/rest-api/shop/eu-withdrawal/list-eu-withdrawals.md","filePath":"api/rest-api/shop/eu-withdrawal/list-eu-withdrawals.md","lastUpdated":1784902076000}`),i={name:"api/rest-api/shop/eu-withdrawal/list-eu-withdrawals.md"};function o(s,t,n,l,c,h){return a(),d("div",null,t[0]||(t[0]=[r('<h1 id="list-eu-withdrawals" tabindex="-1">List EU Withdrawals <a class="header-anchor" href="#list-eu-withdrawals" aria-label="Permalink to &quot;List EU Withdrawals&quot;">​</a></h1><p>Retrieve a list of the authenticated customer&#39;s <strong>own</strong> EU right-of-withdrawal declarations. Declarations are always scoped to the logged-in customer — a customer can never see another customer&#39;s declarations. Results are ordered newest first.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/eu-withdrawals</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>The response is a plain JSON array. Each item is a withdrawal declaration object.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Declaration ID.</td></tr><tr><td><code>uuid</code></td><td>string</td><td>Stable public identifier for the declaration.</td></tr><tr><td><code>orderId</code></td><td>integer</td><td>Numeric ID of the order the withdrawal applies to.</td></tr><tr><td><code>orderIncrementId</code></td><td>string</td><td>Human-readable order number.</td></tr><tr><td><code>isGuest</code></td><td>boolean</td><td>Whether the declaration was filed on a guest order.</td></tr><tr><td><code>customerEmail</code></td><td>string</td><td>Email address tied to the declaration.</td></tr><tr><td><code>status</code></td><td>string</td><td>Declaration status: <code>received</code>, <code>declined</code>, <code>refunded</code>.</td></tr><tr><td><code>reasonText</code></td><td>string</td><td>The reason the shopper supplied, or <code>null</code>.</td></tr><tr><td><code>receivedAt</code></td><td>string</td><td>ISO 8601 timestamp when the declaration was received.</td></tr><tr><td><code>confirmationSentAt</code></td><td>string</td><td>ISO 8601 timestamp when the confirmation email was sent, or <code>null</code>.</td></tr><tr><td><code>declinedAt</code></td><td>string</td><td>ISO 8601 timestamp when the withdrawal was declined, or <code>null</code>.</td></tr><tr><td><code>declinedReason</code></td><td>string</td><td>Reason the store declined the withdrawal, or <code>null</code>.</td></tr><tr><td><code>refundedAt</code></td><td>string</td><td>ISO 8601 timestamp when the order was refunded, or <code>null</code>.</td></tr><tr><td><code>refundNote</code></td><td>string</td><td>Note attached to the refund, or <code>null</code>.</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>ISO 8601 creation timestamp.</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>ISO 8601 last update timestamp.</td></tr></tbody></table><h2 id="empty-collection" tabindex="-1">Empty Collection <a class="header-anchor" href="#empty-collection" aria-label="Permalink to &quot;Empty Collection&quot;">​</a></h2><p>When the customer has no declarations, the response is an empty array:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]</span></span></code></pre></div><h2 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200 OK</code></td><td>Declarations returned.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid customer Bearer token.</td></tr><tr><td><code>403 Forbidden</code></td><td>Missing or invalid storefront key.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/eu-withdrawal/view-eu-withdrawal.html">View EU Withdrawal</a></li><li><a href="/api/rest-api/shop/eu-withdrawal/create-eu-withdrawal.html">File a Withdrawal</a></li><li><a href="/api/rest-api/shop/eu-withdrawal/">EU Withdrawal Overview</a></li></ul>',18)]))}const m=e(i,[["render",o]]);export{p as __pageData,m as default};
